from app.services import create_project

router = APIRouter(prefix="/projects", tags=["projects"])


@router.post("", response_model=ProjectPublic, status_code=201)
def create(payload: ProjectCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):
    return create_project(db, current_user, payload)


@router.get("", response_model=list[ProjectPublic])
def list_owned(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):
    stmt = select(Project).where(Project.owner_id == current_user.id).order_by(Project.created_at.desc(), Project.id.desc())
    return list(db.scalars(stmt))


